// 요청 구성 — 앱이 보낸 {request_id, photo_kind, target_label, image} → OpenRouter chat/completions 본문
// 모델 ID는 기존 기기 라벨 워크플로와 같은 값을 Brad가 채운다 (n8n/README.md). 추측값을 넣지 않는다.
const MODEL = '<<OPENROUTER_MODEL_ID>>';
const KIND_HINT = {
  PART: '부품 라벨 또는 칩 마킹 (품번, 칩 윗면 마킹)',
  BOARD: '메인보드 실크 인쇄 (보드 번호, 예: LA-K091P, NM-D451, BA92-12345A, DA0X8CMB8E0)',
  DEVICE: '기기 라벨 스티커 (모델 번호·SKU, 예: 15Z90T-GP5HL, NT950QED-KC71S)',
};
const body = $input.first().json.body ?? {};
if (!KIND_HINT[body.photo_kind] || typeof body.image !== 'string' || !body.image.startsWith('data:image/')) {
  throw new Error('invalid request');
}
const system = [
  '너는 수리점 사진에서 인쇄된 번호만 읽는 판독기다.',
  '사진에 실제로 보이는 품번, 마킹, 보드 번호, 모델 번호만 그대로 옮겨 적는다. 추측하거나 만들어 내지 않는다.',
  '사람 이름, 전화번호, 주소, 이메일, 시리얼 번호, 바코드 아래 긴 숫자는 절대 출력하지 않는다.',
  '반드시 JSON 하나만 출력한다: {"readings":[{"text":"...","type":"PART_NUMBER|MARKING|BOARD_NUMBER|MODEL_NUMBER|OTHER","confidence":0.0-1.0,"note":"짧은 설명"}]}',
  'readings는 최대 10개. 읽을 것이 없으면 {"readings":[]}.',
].join('\n');
return [{
  json: {
    openrouter: {
      model: MODEL,
      temperature: 0,
      max_tokens: 800,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        {
          role: 'user',
          content: [
            { type: 'text', text: `사진 종류: ${KIND_HINT[body.photo_kind]}\n대상(참고): ${String(body.target_label ?? '').slice(0, 150)}` },
            { type: 'image_url', image_url: { url: body.image } },
          ],
        },
      ],
    },
  },
}];

// 응답 검증 — 모델 출력에서 형식에 맞는 판독만 남긴다. 최종 검증(개인정보·길이·중복)은 DB 함수 ai_photo_propose가 다시 한다.
const TYPES = ['PART_NUMBER', 'MARKING', 'BOARD_NUMBER', 'MODEL_NUMBER', 'OTHER'];
const res = $input.first().json;
let content = res?.choices?.[0]?.message?.content ?? '';
if (Array.isArray(content)) content = content.map((p) => p?.text ?? '').join('');
const cleaned = String(content).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const parsed = JSON.parse(cleaned); // 형식 오류 → 오류 출력(502)
const readings = (Array.isArray(parsed?.readings) ? parsed.readings : [])
  .filter((r) => r && typeof r.text === 'string' && r.text.trim() !== '')
  .slice(0, 10)
  .map((r) => ({
    text: r.text.trim().slice(0, 150),
    type: TYPES.includes(r.type) ? r.type : 'OTHER',
    confidence: Math.min(1, Math.max(0, Number(r.confidence) || 0)),
    note: typeof r.note === 'string' && r.note.trim() !== '' ? r.note.trim().slice(0, 300) : null,
  }));
return [{ json: { readings, model: String(res?.model ?? '').slice(0, 100), execution_id: String($execution.id) } }];
